-- =====================================================================
-- ZORION SAÚDE — DESFAZER A CONSOLIDAÇÃO DE CADASTROS (recuperação)
-- =====================================================================
-- Reverte o merge que juntou apresentações diferentes (QUETIAPINA 25 MG com
-- 100 MG, por exemplo). O agrupamento olhou só o nome, ignorando concentração
-- e apresentação — neste banco nenhum dos 42 nomes repetidos era duplicado.
--
-- A lista de cadastros a restaurar é lida do ARQUIVO do próprio merge
-- ("Medicamento_arquivo_consolidado_2026_10_31"), não recalculada: é o
-- registro do que realmente aconteceu.
--
-- O vínculo original de cada lote/saída/entrada/prescrição foi reconstruído
-- a partir do backup de 16/10 (mesmos ids). Registros criados depois dessa
-- data permanecem no cadastro que sobreviveu — a conferência no fim mostra
-- quantos são.
--
-- Nada é apagado. Rode com o aplicativo fechado.
-- =====================================================================

-- 0. CONFERÊNCIA PRÉVIA (não altera nada) -----------------------------
-- Mostra exatamente quem será reativado. O cadastro que SOBREVIVEU ao merge
-- não está nesta tabela — por isso ele não é tocado e não há duplicação.
SELECT nome, concentracao, apresentacao, estoque_atual, estoque_satelite
  FROM "Medicamento_arquivo_consolidado_2026_10_31"
 ORDER BY nome, concentracao;

DO $$
DECLARE
    conflito integer;
BEGIN
    -- Trava: ninguém pode ser absorvido e sobrevivente ao mesmo tempo.
    SELECT count(*) INTO conflito
      FROM "Medicamento_arquivo_consolidado_2026_10_31" a
      JOIN "Medicamento_arquivo_consolidado_2026_10_31" b ON b.id_sobrevivente = a.id;

    IF conflito > 0 THEN
        RAISE EXCEPTION
            'ABORTADO: % cadastro(s) aparecem como absorvido e sobrevivente. Nada foi alterado.', conflito;
    END IF;
END $$;

BEGIN;

-- 1. reativar os cadastros absorvidos --------------------------------
UPDATE "Medicamento" m
   SET ativo = true,
       deleted_at = NULL
  FROM "Medicamento_arquivo_consolidado_2026_10_31" a
 WHERE m.id = a.id;

-- 2. devolver 78 registro(s) de Lote ao cadastro de origem
CREATE TEMP TABLE tmp_Lote (id text, medicamento_id text) ON COMMIT DROP;
UPDATE "Lote" x SET medicamento_id = t.medicamento_id
  FROM tmp_Lote t WHERE x.id = t.id;

-- 2. devolver 34 registro(s) de Saida ao cadastro de origem
CREATE TEMP TABLE tmp_Saida (id text, medicamento_id text) ON COMMIT DROP;
UPDATE "Saida" x SET medicamento_id = t.medicamento_id
  FROM tmp_Saida t WHERE x.id = t.id;

-- 2. devolver 78 registro(s) de Entrada ao cadastro de origem
CREATE TEMP TABLE tmp_Entrada (id text, medicamento_id text) ON COMMIT DROP;
UPDATE "Entrada" x SET medicamento_id = t.medicamento_id
  FROM tmp_Entrada t WHERE x.id = t.id;

-- 2. devolver 22 registro(s) de TransferenciaPendente ao cadastro de origem
CREATE TEMP TABLE tmp_TransferenciaPendente (id text, medicamento_id text) ON COMMIT DROP;
UPDATE "TransferenciaPendente" x SET medicamento_id = t.medicamento_id
  FROM tmp_TransferenciaPendente t WHERE x.id = t.id;

-- 2. devolver 296 registro(s) de PrescricaoPaciente ao cadastro de origem
CREATE TEMP TABLE tmp_PrescricaoPaciente (id text, medicamento_id text) ON COMMIT DROP;
UPDATE "PrescricaoPaciente" x SET "medicamentoId" = t.medicamento_id
  FROM tmp_PrescricaoPaciente t WHERE x.id = t.id;

-- 3. saldos -----------------------------------------------------------
-- 3.1 o absorvido volta ao valor exato de antes (está no arquivo)
UPDATE "Medicamento" m
   SET estoque_atual    = a.estoque_atual,
       estoque_satelite = a.estoque_satelite
  FROM "Medicamento_arquivo_consolidado_2026_10_31" a
 WHERE m.id = a.id;

-- 3.2 o sobrevivente perde o que tinha sido somado nele
UPDATE "Medicamento" m
   SET estoque_atual    = greatest(0, m.estoque_atual    - t.central),
       estoque_satelite = greatest(0, m.estoque_satelite - t.satelite)
  FROM (
      SELECT id_sobrevivente,
             sum(coalesce(estoque_atual,0))    AS central,
             sum(coalesce(estoque_satelite,0)) AS satelite
        FROM "Medicamento_arquivo_consolidado_2026_10_31"
       GROUP BY id_sobrevivente
  ) t
 WHERE m.id = t.id_sobrevivente;

COMMIT;

-- 4. conferência ------------------------------------------------------
SELECT count(*) AS cadastros_reativados
  FROM "Medicamento"
 WHERE id IN (SELECT id FROM "Medicamento_arquivo_consolidado_2026_10_31");

SELECT nome, concentracao, apresentacao, estoque_atual, estoque_satelite
  FROM "Medicamento"
 WHERE upper(nome) LIKE '%QUETIAPINA%' AND deleted_at IS NULL
 ORDER BY concentracao;

SELECT coalesce(sum(coalesce(estoque_atual,0)),0)    AS central_total,
       coalesce(sum(coalesce(estoque_satelite,0)),0) AS satelite_total
  FROM "Medicamento" WHERE deleted_at IS NULL;
